<script lang="ts">
  import { onMount } from 'svelte';
  import { listen } from '@tauri-apps/api/event';
  import { FolderOpen, FolderPlus, Search, Play, ListPlus, ListStart, LoaderCircle, RefreshCw, Settings2, ChevronDown } from 'lucide-svelte';
  import { invoke } from './backend';
  import LocalArtwork from './LocalArtwork.svelte';
  import type { Item, LocalPage, Endpoint } from './types';
  let {onplay,onqueue,onsettings,currentId=''}:{onplay:(item:Item,items:Item[],continuation:Endpoint|null)=>void;onqueue:(item:Item,next:boolean)=>void;onsettings:()=>void;currentId?:string}=$props();
  let data=$state<LocalPage|null>(null),query=$state(''),artist=$state(''),album=$state(''),loading=$state(true),more=$state(false),error=$state(''),busy=$state(false);
  let version=0;
  async function load(append=false){const id=++version;if(append)more=true;else loading=true;error='';try{const result=await invoke<LocalPage>('local_library',{query,artist,album,offset:append?data?.items.length??0:0});if(id!==version)return;data=append&&data?{...result,items:[...data.items,...result.items]}:result;}catch(e){if(id===version)error=String(e);}finally{if(id===version){loading=false;more=false;}}}
  $effect(()=>{query;artist;album;const timer=setTimeout(()=>void load(),180);return()=>clearTimeout(timer);});
  async function add(){busy=true;try{await invoke('choose_music_folder');await load();}catch(e){error=String(e);}finally{busy=false;}}
  const continuation=$derived(data && data.items.length<data.total ? {localQuery:{query,artist,album},offset:data.items.length} : null);
  onMount(()=>{let disposed=false,unlisten:(()=>void)|undefined;void listen('local-library-updated',()=>{void load();}).then(f=>{if(disposed)f();else unlisten=f;});return()=>{disposed=true;version++;unlisten?.();};});
</script>
<div class="page-heading"><div><span class="eyebrow">ТВОЯ ЛОКАЛЬНАЯ КОЛЛЕКЦИЯ</span><h1>На устройстве</h1></div><div class="local-actions"><button class="secondary" onclick={onsettings}><Settings2 size={16}/>Папки</button><button class="primary" disabled={busy} onclick={add}><FolderPlus size={16}/>Добавить папку</button></div></div>
<div class="local-filters"><label><Search size={17}/><input aria-label="Поиск локальной музыки" placeholder="Название, исполнитель, альбом" bind:value={query}/></label><div class="local-select"><select aria-label="Локальный исполнитель" bind:value={artist} onchange={()=>album=''}><option value="">Все исполнители</option>{#each data?.artists??[] as name}<option value={name}>{name}</option>{/each}</select><ChevronDown size={15}/></div><div class="local-select"><select aria-label="Локальный альбом" bind:value={album}><option value="">Все альбомы</option>{#each data?.albums??[] as name}<option value={name}>{name}</option>{/each}</select><ChevronDown size={15}/></div></div>
{#if data?.status.scanning}<p class="local-status"><LoaderCircle class="spin" size={14}/>Обновляем коллекцию…</p>{:else if data}<p class="local-status">{data.total} треков{#if data.status.folders.some(f=>!f.available)} · Есть отключённые папки{/if}</p>{/if}
{#if error}<div class="empty-state"><p>{error}</p><button class="secondary" onclick={()=>load()}><RefreshCw size={15}/>Повторить</button></div>
{:else if loading&&!data}<div class="empty-state"><LoaderCircle class="spin" size={30}/></div>
{:else if !data?.items.length}<div class="empty-state"><FolderOpen size={42}/><h2>{query||artist||album?'Ничего не нашлось':'Музыка, которая всегда с тобой'}</h2><p>{query||artist||album?'Попробуй изменить поиск или фильтры.':'Подключи папку с MP3, FLAC, M4A, Ogg, Opus или WAV. Музыка будет доступна без интернета.'}</p>{#if !data?.status.folders.length}<button class="primary" onclick={add}><FolderPlus size={16}/>Выбрать папку с музыкой</button>{/if}</div>
{:else}<div class="track-list local-tracks">{#each data.items as item,n (item.id)}<div class="track-actions-row" class:unavailable={item.available===false}><button class="track-row" class:playing={currentId===item.id} disabled={item.available===false} onclick={()=>onplay(item,data!.items,continuation)}><span class="track-number">{currentId===item.id?'♪':n+1}</span><span class="local-cover"><LocalArtwork {item}/></span><span class="track-details"><strong>{item.title}</strong><small>{item.available===false?'Файл недоступен · ':''}{item.subtitle || 'Без тегов'}</small></span><span class="track-duration">{item.duration}</span><Play size={15}/></button><div class="track-extra"><button class="icon" disabled={item.available===false} aria-label={`Воспроизвести следующим: ${item.title}`} onclick={()=>onqueue(item,true)}><ListStart size={17}/></button><button class="icon" disabled={item.available===false} aria-label={`Добавить в очередь: ${item.title}`} onclick={()=>onqueue(item,false)}><ListPlus size={17}/></button></div></div>{/each}</div>{#if continuation}<div class="load-more"><button class="secondary" disabled={more} onclick={()=>load(true)}>{#if more}<LoaderCircle size={15} class="spin"/>{/if}Ещё треки</button></div>{/if}{/if}
{#if data?.status.warning}<p class="local-status">{data.status.warning}</p>{/if}
<style>.local-tracks{grid-template-columns:repeat(auto-fit,minmax(min(100%,400px),1fr))}.local-actions{display:flex;gap:9px;flex-wrap:wrap}.local-filters{display:flex;gap:12px;margin-bottom:18px;flex-wrap:wrap}.local-filters label{display:flex;gap:10px;align-items:center;flex:1;min-width:200px;border:1px solid var(--line);background:var(--surface);border-radius:11px;padding:11px 14px;color:var(--muted)}.local-filters label>:global(svg){flex-shrink:0}.local-filters input{min-width:0;border:0;background:none;color:var(--text);outline:none;width:100%;font:inherit;font-size:12px}.local-select{position:relative;min-width:150px;max-width:230px;flex:0 1 230px}.local-select>:global(svg){position:absolute;right:12px;top:50%;transform:translateY(-50%);pointer-events:none;color:var(--muted)}.local-filters select{appearance:none;width:100%;min-width:0;height:100%;text-overflow:ellipsis;white-space:nowrap;overflow:hidden;border:1px solid var(--line);background:var(--surface);color:var(--text);border-radius:11px;padding:11px 36px 11px 12px;font:inherit;font-size:12px}.local-status{display:flex;align-items:center;gap:9px;color:var(--muted);font-size:12px;margin:18px 0}.local-cover{width:42px;height:42px;flex-shrink:0;border-radius:7px;overflow:hidden}.unavailable{opacity:.5}</style>
